SourceCode.Declaration:
/// <summary>
/// Capture context that bridges the two print path extension points. Opened by the
/// <c>printDocument</c> extension when a label is printed for a Work record, and used by the
/// <c>printLabelToPrinter</c> extension to stage every ZPL label printed while the scope is active.
/// Scopes can nest; disposing a scope restores the previous one.
/// </summary>
public final class AAXWHSLabelCaptureScope implements System.IDisposable
{
    private static AAXWHSLabelCaptureScope currentScope;

    private AAXWHSLabelCaptureScope previousScope;
    private boolean                 active;
    private WHSWorkId               workId;
    private WHSLicensePlateId       licensePlateId;
    private WHSWorkTransType        workTransType;
    private Set                     stagedHashes;
}

Method.Source:
/// <summary>
/// Initializes a new instance of the <c>AAXWHSLabelCaptureScope</c> class.
/// </summary>
protected void new()
{
    stagedHashes = new Set(Types::String);
}

/// <summary>
/// Opens a capture scope for the label's Work context and makes it current. The scope is always
/// created so the caller can call next unconditionally; an inactive scope stages nothing.
/// The caller must dispose the scope.
/// </summary>
/// <param name = "_label">The license plate label being printed.</param>
/// <param name = "_active">True when capture is enabled for this label.</param>
/// <returns>The new current scope.</returns>
public static AAXWHSLabelCaptureScope newFromLabel(WHSLicensePlateLabel _label, boolean _active)
{
    AAXWHSLabelCaptureScope scope = new AAXWHSLabelCaptureScope();

    scope.active         = _active;
    scope.workId         = _label.WorkId;
    scope.licensePlateId = _label.LicensePlateId;
    scope.workTransType  = _label.WorkTransType;

    scope.previousScope = currentScope;
    currentScope = scope;

    return scope;
}

/// <summary>
/// Gets the active capture scope for this session.
/// </summary>
/// <returns>The current scope, or null when no capture is in progress.</returns>
public static AAXWHSLabelCaptureScope current()
{
    return currentScope;
}

/// <summary>
/// Stages one final ZPL label for rendering. A per-scope hash set prevents staging the same label
/// twice within one print operation, and the render dimensions are left at 0 so the renderer reads
/// them from the ZPL with the parameter fallbacks. The insert runs in the caller's transaction so
/// a rolled-back print discards its staging row.
/// </summary>
/// <param name = "_printerName">The printer the label was routed to.</param>
/// <param name = "_zpl">The final, token-substituted ZPL.</param>
public void stageLabel(WHSPrinterName _printerName, str _zpl)
{
    if (!active || !_zpl)
    {
        return;
    }

    // The hash implementation is shared with the renderer
    str zplHash = AtomicAx.Zpl.Render.ZplRenderService::ComputeHash(_zpl);

    if (stagedHashes.in(zplHash))
    {
        return;
    }
    stagedHashes.add(zplHash);

    AAXWHSLabelCaptureStaging staging;

    staging.FinalZpl       = _zpl;
    staging.ZplHash        = zplHash;
    staging.WorkId         = workId;
    staging.LicensePlateId = licensePlateId;
    staging.PrinterName    = _printerName;
    staging.Status         = AAXWHSLabelCaptureStatus::Pending;

    // Only stage here; rendering runs after the print transaction commits
    staging.insert();
}

/// <summary>
/// Indicates whether this scope is capturing labels.
/// </summary>
/// <returns>True if capture is enabled for this scope.</returns>
public boolean isActive()
{
    return active;
}

/// <summary>
/// Rebuilds and stages the final ZPL for a label layout routing line using the same layout and
/// translator the print path uses, so capture works when no printer is configured. Only plain
/// ZPL layouts are handled; Variables and template translator layouts are skipped.
/// </summary>
/// <param name = "_routingLine">The label layout routing line resolved for this label.</param>
/// <param name = "_label">The license plate label being printed.</param>
public void stageLabelLayoutLine(WHSDocumentRoutingLabelLayoutLine _routingLine, WHSLicensePlateLabel _label)
{
    if (!active)
    {
        return;
    }

    WHSLabelLayout labelLayout = WHSLabelLayout::findRecId(_routingLine.LabelLayout);

    if (!labelLayout.RecId
        || labelLayout.DefinitionType != WHSLabelLayoutDefinitionType::ZPL
        || labelLayout.EnableTemplateTranslator)
    {
        return;
    }

    WHSLabelLayoutVersion layoutVersion;
    select firstonly ZPL from layoutVersion
        where layoutVersion.RecId == labelLayout.ActiveVersion;

    if (!layoutVersion.ZPL)
    {
        return;
    }

    WhsDocumentRoutingTranslator translator = WhsDocumentRoutingTranslator::construct();

    if (labelLayout.LabelLocale)
    {
        translator.withLanguage(labelLayout.LabelLocale);
    }

    translator.withRecord(_routingLine, 'routingLine');
    translator.withRecord(_label);

    str finalZpl = translator.translate(layoutVersion.ZPL);

    this.stageLabel(_routingLine.PrinterName, finalZpl);
}

/// <summary>
/// Closes the scope and restores the previous scope.
/// </summary>
public void Dispose()
{
    currentScope = previousScope;
    previousScope = null;
}
